#!/usr/bin/env node
// Offline self-test for the README renderer: ranking, nulls, and idempotence.
// The point is that a visitor's table can be regenerated byte-for-byte.
const assert = require("assert");
const lb = require("./leaderboard.js");

const README = `# t\n\n${lb.START}\nstale\n${lb.END}\n\ntail\n`;
const results = {
  generated_at: "2026-01-02T03:04:05.000Z",
  reps: 3,
  tasks: { a: { default: 1 }, b: { default: 2 } },
  entries: [
    {
      harness: "mini-loop",
      model: "m-big",
      status: "complete",
      vanilla: { pass_at_1: 1, tax: 6.63, cost_per_task: 0 },
      minimal: { pass_at_1: 1, tax: 5.62, cost_per_task: 0 },
      minimality_delta: { overall: 1.01 },
    },
    {
      harness: "mini-loop",
      model: "m-small",
      status: "complete",
      vanilla: { pass_at_1: 0.67, tax: null, cost_per_task: null },
      minimal: { pass_at_1: 0.67, tax: null, cost_per_task: null },
      minimality_delta: { overall: 0 },
    },
    // Partial runs emit entries that were never scored at all.
    { harness: "mini-loop", model: "m-pending", status: "in_progress" },
  ],
};

const out = lb.splice(README, lb.render(results));

assert.match(out, /m-big/, "entries are listed");
assert.match(out, /6\.63×/, "tax is rendered");
assert.match(out, /15%/, "savings are computed from the two tax values");
assert.match(out, /2026-01-02/, "the run date is visible");
assert.match(out, /m-small/, "an entry with no taxable group is still listed");
assert.match(out, /\*\*—\*\*/, "a null tax renders as a dash, never as a number");
assert.match(out, /2 tasks/, "the task count comes from the results file");
assert.match(out, /m-pending/, "an entry that was never scored is still listed");
assert.match(out, /not scored yet \(in_progress\)/, "an unscored entry says so instead of crashing the renderer");
assert.ok(!out.includes("stale"), "the previous block is replaced");
assert.ok(out.startsWith("# t\n"), "text before the block is untouched");
assert.ok(out.trimEnd().endsWith("tail"), "text after the block is untouched");
assert.strictEqual(lb.splice(out, lb.render(results)), out, "rendering twice changes nothing");
assert.throws(() => lb.splice("# no markers\n", "x"), /markers/, "a README without markers fails loudly");

console.log("test_leaderboard: PASS (ranks by tax, nulls render as dashes, idempotent)");
